-- kernel_private.stamp_binding_provenance() (ADR-0023 revision 2.5, section 27.9): the one B1 SECURITY DEFINER exception. It runs with the
-- owner's rights so that no runtime role needs the write its body performs. Its body is not touched: this migration
-- contains no CREATE FUNCTION for it and changes only its security attributes and its EXECUTE ACL.
alter function kernel_private.stamp_binding_provenance() security definer;
alter function kernel_private.stamp_binding_provenance() set search_path = '';
revoke all on function kernel_private.stamp_binding_provenance() from public;
do $$ declare g record; begin
  for g in select distinct pg_get_userbyid(a.grantee) as grantee from pg_proc p, aclexplode(p.proacl) a
    where p.oid = 'kernel_private.stamp_binding_provenance()'::regprocedure and a.grantee <> 0 and a.grantee <> p.proowner loop
    execute format('revoke all on function kernel_private.stamp_binding_provenance() from %I', g.grantee);
  end loop;
end $$;

