do $$ declare f record; n int; begin
  select p.prosecdef, p.proconfig, p.proacl is null as acl_null,
         encode(sha256(convert_to(replace(p.prosrc, E'\r\n', E'\n'), 'UTF8')), 'hex') as digest,
         (select count(*) from aclexplode(p.proacl) a where not (a.grantee = p.proowner and a.grantor = p.proowner
            and a.privilege_type = 'EXECUTE' and not a.is_grantable)) as foreign_acl,
         (select count(*) from aclexplode(p.proacl) a) as acl_items
    into f from pg_proc p where p.oid = 'kernel_private.stamp_binding_provenance()'::regprocedure;
  if not f.prosecdef then raise exception 'B1: kernel_private.stamp_binding_provenance() is not SECURITY DEFINER' using errcode = '23514'; end if;
  if f.proconfig is distinct from array['search_path=""'] then
    raise exception 'B1: proconfig of kernel_private.stamp_binding_provenance() is %, sealed is the one element search_path=""', f.proconfig using errcode = '23514'; end if;
  if f.acl_null or f.acl_items <> 1 or f.foreign_acl <> 0 then
    raise exception 'B1: EXECUTE ACL of kernel_private.stamp_binding_provenance() is not exactly the owner''s' using errcode = '23514'; end if;
  if f.digest <> '468979611a28ca8e2ec7b46f16402e90ae6622a228e186e1acc7ac45186e439b' then
    raise exception 'B1: source digest of kernel_private.stamp_binding_provenance() is %, pinned 468979611a28ca8e2ec7b46f16402e90ae6622a228e186e1acc7ac45186e439b', f.digest using errcode = '23514'; end if;
  select count(*) into n from pg_proc p join pg_namespace s on s.oid = p.pronamespace where p.proname = 'stamp_binding_provenance'
    and not (s.nspname in ('pg_catalog', 'information_schema', 'pg_toast') or s.nspname ~ '^pg_temp_[0-9]+$' or s.nspname ~ '^pg_toast_temp_[0-9]+$');
  if n <> 1 then raise exception 'B1: % functions are named stamp_binding_provenance; exactly one is sealed', n using errcode = '23514'; end if;
  select count(*) into n from pg_proc p join pg_namespace s on s.oid = p.pronamespace where p.prosecdef and s.nspname in ('public', 'kernel_private');
  if n <> 1 then raise exception 'B1: KernelJSON schemas hold % SECURITY DEFINER functions; stage B1 allows exactly one', n using errcode = '23514'; end if;
end $$;

-- Pre-COMMIT self-check: refuse to commit a role that is not exactly as sealed.
do $$ declare bad text; begin
  select string_agg(rolname, ', ') into bad from pg_roles where rolname in ('kj_worker', 'kj_door')
    and (not rolcanlogin or rolsuper or rolcreatedb or rolcreaterole or rolreplication or rolbypassrls or rolinherit);
  if bad is not null then raise exception 'B1: runtime role attributes are not as sealed: %', bad using errcode = '23514'; end if;
  if exists (select 1 from pg_auth_members m where m.member::regrole::text in ('kj_worker', 'kj_door') or m.roleid::regrole::text in ('kj_worker', 'kj_door')) then
    raise exception 'B1: a runtime role has a role membership' using errcode = '23514'; end if;
end $$;
